#define MAX_TEAMS 100
#define MAX_PROBLEMS 10

typedef struct {
    int team_num;
    int solved;
    int total_time;
    int penalties[MAX_PROBLEMS + 1]; // 1-indexed problems
    int solved_problems[MAX_PROBLEMS + 1];
} Team;

Team teams[MAX_TEAMS];
int team_count;

int compare_teams(const void *a, const void *b) {
    Team *team_a = (Team *)a;
    Team *team_b = (Team *)b;

    if (team_a->solved != team_b->solved)
        return team_b->solved - team_a->solved; // more solved first
    if (team_a->total_time != team_b->total_time)
        return team_a->total_time - team_b->total_time; // less time first
    return 0; // equal rank
}

int find_team(int team_num) {
    for (int i = 0; i < team_count; i++) {
        if (teams[i].team_num == team_num)
            return i;
    }
    return -1;
}

