#define MAXT 105
#define MAXP 15

typedef struct {
    int id;
    int solved;
    int penalty;
} Team;

int solved[MAXT][MAXP];
int wrongs[MAXT][MAXP];
int activeTeam[MAXT];

int cmp(const void *a, const void *b) {
    const Team *x = (const Team *)a;
    const Team *y = (const Team *)b;

    if (x->solved != y->solved) return y->solved - x->solved;   // more solved first
    if (x->penalty != y->penalty) return x->penalty - y->penalty; // less penalty first
    return x->id - y->id; // stable output by team number inside same rank
}

int main(void) {
    int M, T, P, R;
    int firstDataset = 1;

    while (scanf("%d %d %d %d", &M, &T, &P, &R) == 4) {
        if (M == 0 && T == 0 && P == 0 && R == 0) break;

        memset(solved, 0, sizeof(solved));
        memset(wrongs, 0, sizeof(wrongs));
        memset(activeTeam, 0, sizeof(activeTeam));

        Team teams[MAXT];
        for (int i = 1; i <= T; i++) {
            teams[i-1].id = i;
            teams[i-1].solved = 0;
            teams[i-1].penalty = 0;
            activeTeam[i] = 1;  // all teams participate in ranking
        }

        for (int i = 0; i < R; i++) {
            int m, t, p, j;
            scanf("%d %d %d %d", &m, &t, &p, &j);

            if (solved[t][p]) continue; // already solved, ignore later submissions

            if (j == 0) { // accepted
                solved[t][p] = 1;
                teams[t-1].solved++;
                teams[t-1].penalty += m + wrongs[t][p] * 20;
            } else { // rejected
                wrongs[t][p]++;
            }
        }

        qsort(teams, T, sizeof(Team), cmp);

        if (!firstDataset) printf("\n");
        firstDataset = 0;

        for (int i = 0; i < T; i++) {
            if (i > 0) {
                if (teams[i].solved == teams[i-1].solved &&
                    teams[i].penalty == teams[i-1].penalty) {
                    printf("=");
                } else {
                    printf(",");
                }
            }
            printf("%d", teams[i].id);
        }
        printf("\n");
    }

    return 0;
}

