import sys

def solve():
    out = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        M, T, P, R = map(int, line.split())
        if M == 0 and T == 0 and P == 0 and R == 0:
            break

        # wrong[team][problem] = number of wrong submissions before accepted
        wrong = [[0] * (P + 1) for _ in range(T + 1)]
        solved_problem = [[False] * (P + 1) for _ in range(T + 1)]
        solved_cnt = [0] * (T + 1)
        penalty = [0] * (T + 1)

        for _ in range(R):
            m, t, p, j = sys.stdin.readline().split()
            m = int(m)
            t = int(t)
            p = int(p)

            if solved_problem[t][p]:
                continue

            if j == "CORRECT":
                solved_problem[t][p] = True
                solved_cnt[t] += 1
                penalty[t] += m + 20 * wrong[t][p]
            else:
                wrong[t][p] += 1

        teams = list(range(1, T + 1))
        teams.sort(key=lambda x: (-solved_cnt[x], penalty[x], x))

        parts = []
        prev = None
        for idx, team in enumerate(teams):
            cur = (solved_cnt[team], penalty[team])
            if idx == 0:
                parts.append(str(team))
            else:
                if cur == prev:
                    parts.append("=" + str(team))
                else:
                    parts.append("," + str(team))
            prev = cur

        out.append("".join(parts))

    sys.stdout.write("\n".join(out))

