public class Main {
    static class Team {
        int id;
        int solved = 0;
        int time = 0;
        int[] wrong;
        boolean[] solvedProb;

        Team(int id, int m) {
            this.id = id;
            wrong = new int[m + 1];
            solvedProb = new boolean[m + 1];
        }
    }

    static class Result {
        int id, solved, time;
        Result(int id, int solved, int time) {
            this.id = id;
            this.solved = solved;
            this.time = time;
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        StringBuilder out = new StringBuilder();

        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;

            StringTokenizer st = new StringTokenizer(line);
            int M = Integer.parseInt(st.nextToken()); // problems
            int T = Integer.parseInt(st.nextToken()); // teams
            int P = Integer.parseInt(st.nextToken()); // submissions
            int R = Integer.parseInt(st.nextToken()); // penalty

            if (M == 0 && T == 0 && P == 0 && R == 0) break;

            Team[] teams = new Team[T + 1];
            for (int i = 1; i <= T; i++) teams[i] = new Team(i, M);

