                return Integer.compare(a.id, b.id);
            });

            for (int i = 0; i < list.size(); i++) {
                if (i > 0) {
                    Result prev = list.get(i - 1);
                    Result cur = list.get(i);
                    if (prev.solved == cur.solved && prev.time == cur.time) out.append('=');
